function draw() {
	const dataMetaballs = [],
				dataMetaballColors = [];

	for (const ball of metaballs) {
		ball.update();
		dataMetaballs.push(ball.pos.x, ball.pos.y, ball.radius);
		dataMetaballColors.push(...ball.color);
	}

	metaballShader.setUniform("metaballs",      dataMetaballs);
	metaballShader.setUniform("metaballColors", dataMetaballColors);
	rect(0, 0, width, height);
}

// OpenProcessing has a bug where it always creates a scrollbar on Chromium.
function mouseWheel() { // This stops the canvas from scrolling by a few pixels.
	return false;
}

// === Tab: metaball ===
class Metaball {
	constructor() {
		const size = Math.pow(Math.random(), 2);
		this.vel = p5.Vector.random2D().mult(.5 * (1 - size) - 1);
		this.radius = 100 * size + 20;
		this.color = color(random(theme.colors))._array.slice(0, 3);

		this.pos = new p5.Vector(random(this.radius, width - this.radius), random(this.radius, height - this.radius));
	}

	update() {
		this.pos.add(this.vel);

		if (this.pos.x < this.radius || this.pos.x > width  - this.radius) this.vel.x *= -1;
		if (this.pos.y < this.radius || this.pos.y > height - this.radius) this.vel.y *= -1;
	}
}

// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec3 metaballs[${N_balls}];
		uniform vec3 metaballColors[${N_balls}];

		const float WIDTH = ${windowWidth}.0;
		const float HEIGHT = ${windowHeight}.0;

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;

			vec3 colorTotal = vec3(0.0);
			for (int i = 0; i < ${N_balls}; i++) {
				vec3 ball = metaballs[i];
				float dx = ball.x - x;
				float dy = ball.y - y;
				float r = ball.z;
				v += r * r / (dx * dx + dy * dy);
				colorTotal += metaballColors[i] * v / 10.0;
			}

			// if (v > 1.0) gl_FragColor = vec4(x / WIDTH, y / HEIGHT, 0.0, 1.0);
			// else gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
			gl_FragColor = vec4(colorTotal, 1.0);
		}
	`;

	return createShader(vert, frag);
}

